package com.arena.core.sessions;

import com.arena.core.checkin.*;
import static com.arena.core.checkin.FacilityCheckinContracts.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.arena.core.training.*;
import com.arena.core.facility.FacilityService;
import com.arena.core.repository.CustomerRepository;
import com.arena.core.service.CustomerAccessService;
import com.arena.core.exception.ArenaOpsException;
import com.arena.core.entity.AppUserEntity;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.*;
import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

@SpringJUnitConfig({SessionCheckoutIntegrationTest.Config.class,FacilityCheckinIntegrationTest.Config.class})
class FacilityCheckinIntegrationTest {
 @Configuration static class Config {
  @Bean CustomerAccessService publicAccess(){var a=mock(CustomerAccessService.class);when(a.isCustomerUsable(any())).thenReturn(true);return a;}
  @Bean FacilityCheckinService checkin(AcademyAuthorization auth,FacilityService facilities,AcademyPlayAreaRepository areas,AcademySportRepository sports,FacilityQrChallengeRepository challenges,FacilityCustomerCheckinRepository checkins,RunningSessionService lifecycle,CustomerRepository customers,CustomerAccessService access){return new FacilityCheckinService(auth,facilities,areas,sports,challenges,checkins,lifecycle,customers,access);}
 }
 @Autowired FacilityCheckinService service;@Autowired FacilityQrChallengeRepository challenges;@Autowired FacilityCustomerCheckinRepository checkins;@Autowired AcademyRunningSessionRepository sessions;@Autowired SessionStopQuoteRepository quotes;@Autowired SessionDiscountRequestRepository discounts;@Autowired com.arena.core.billing.AcademyPaymentRepository payments;
 @Autowired AcademyPlayAreaRepository areas;@Autowired RunningSessionService lifecycle;@Autowired PlatformTransactionManager manager;@Autowired CustomerAccessService access;
 TransactionTemplate tx;AcademyAuthorization.Actor owner;
 @BeforeEach void setup(){tx=new TransactionTemplate(manager);owner=new AcademyAuthorization.Actor(AppUserEntity.builder().id(1L).username("owner").customerId(1L).isActive(true).build(),null,Set.of("OWNER"));SessionCheckoutIntegrationTest.ACTOR.set(owner);tx.executeWithoutResult(t->{checkins.deleteAll();challenges.deleteAll();quotes.deleteAll();discounts.deleteAll();payments.deleteAll();sessions.deleteAll();});when(access.isCustomerUsable(any())).thenReturn(true);var f=areas.findById(1L).orElseThrow();f.setActive(true);f.setHourlyRate(new java.math.BigDecimal("3600"));f.setCode("E1");}
 @AfterEach void clear(){SessionCheckoutIntegrationTest.ACTOR.remove();}
 Challenge issue(){return service.issue(SessionCheckoutIntegrationTest.JWT,1L);}
 Receipt submit(Challenge q){return service.submit(new Submission(q.token(),"Walk-in Customer","+91 98765 43210",true));}
 @Test void quickStartStillRequiresNoQr(){var s=lifecycle.start(SessionCheckoutIntegrationTest.JWT,new RunningSessionContracts.Start(1L,"Manual guest"));assertEquals("STARTED",s.status());assertTrue(checkins.findAll().isEmpty());assertTrue(challenges.findAll().isEmpty());}
 @Test void validRegistrationCreatesOnlyPendingAndStoresTokenHash(){var q=issue();var receipt=submit(q);assertEquals("PENDING",receipt.status());assertTrue(sessions.findAll().isEmpty());assertNotEquals(q.token(),challenges.findAll().get(0).getTokenHash());assertEquals(64,challenges.findAll().get(0).getTokenHash().length());var c=service.pending(SessionCheckoutIntegrationTest.JWT).get(0);assertEquals("+919876543210",c.mobile());assertFalse(c.mobileVerified());assertNull(checkins.findAll().get(0).getSessionId());}
 @Test void invalidExpiredAndReusedQrNeverReturnCustomerData(){var q=issue();assertThrows(ArenaOpsException.class,()->service.inspect("A".repeat(43)));tx.executeWithoutResult(t->{var row=challenges.findAll().get(0);row.setExpiresAt(Instant.now().minusSeconds(1));challenges.save(row);});assertThrows(ArenaOpsException.class,()->submit(q));var fresh=issue();submit(fresh);assertThrows(ArenaOpsException.class,()->submit(fresh));assertThrows(ArenaOpsException.class,()->service.inspect(fresh.token()));assertEquals(1,checkins.findAll().size());}
 @Test void invalidMobileOrMissingConsentDoesNotConsumeChallenge(){var q=issue();assertThrows(ArenaOpsException.class,()->service.submit(new Submission(q.token(),"Guest","123",true)));assertThrows(ArenaOpsException.class,()->service.submit(new Submission(q.token(),"Guest","+919876543210",false)));assertNull(challenges.findAll().get(0).getUsedAt());assertNotNull(submit(q));}
 @Test void multipleChallengesCanQueueCustomersForOneTable(){var q1=issue();var q2=issue();submit(q1);submit(q2);assertEquals(2,service.pending(SessionCheckoutIntegrationTest.JWT).size());assertTrue(sessions.findAll().isEmpty());}
 @Test void confirmationUsesExistingServerStartAndLinksCheckin(){submit(issue());var c=checkins.findAll().get(0);var before=LocalDateTime.now(ZoneId.of("Asia/Kolkata")).minusSeconds(1);var r=service.confirm(SessionCheckoutIntegrationTest.JWT,c.getId(),new Confirm(null));var session=sessions.findById(r.sessionId()).orElseThrow();assertTrue(session.getStartedAt().isAfter(before));assertEquals("Walk-in Customer",session.getPlayerName());assertEquals(0,new java.math.BigDecimal("3600").compareTo(session.getRatePerHour()));assertEquals(session.getId(),checkins.findById(c.getId()).orElseThrow().getSessionId());assertThrows(ArenaOpsException.class,()->service.confirm(SessionCheckoutIntegrationTest.JWT,c.getId(),new Confirm(null)));assertEquals(1,sessions.findAll().size());}
 @Test void competingOperatorStartRollsBackCheckinConfirmation(){submit(issue());var c=checkins.findAll().get(0);lifecycle.start(SessionCheckoutIntegrationTest.JWT,new RunningSessionContracts.Start(1L,"Other operator"));assertThrows(ArenaOpsException.class,()->service.confirm(SessionCheckoutIntegrationTest.JWT,c.getId(),new Confirm(null)));assertEquals("PENDING",checkins.findById(c.getId()).orElseThrow().getStatus());assertNull(checkins.findById(c.getId()).orElseThrow().getSessionId());}
 @Test void conflictingReservationUsesExistingWindowRules(){submit(issue());var c=checkins.findAll().get(0);var now=LocalDateTime.now(ZoneId.of("Asia/Kolkata"));lifecycle.reserve(SessionCheckoutIntegrationTest.JWT,new RunningSessionContracts.Reserve(1L,"Booking",now.plusMinutes(5),now.plusMinutes(30)));assertThrows(ArenaOpsException.class,()->service.confirm(SessionCheckoutIntegrationTest.JWT,c.getId(),new Confirm(now.plusHours(1))));assertEquals("PENDING",checkins.findById(c.getId()).orElseThrow().getStatus());}
 @Test void crossTenantCannotListConfirmOrCancel(){submit(issue());var id=checkins.findAll().get(0).getId();var other=new AcademyAuthorization.Actor(AppUserEntity.builder().id(3L).username("other").customerId(2L).build(),null,Set.of("OWNER"));SessionCheckoutIntegrationTest.ACTOR.set(other);assertTrue(service.pending(SessionCheckoutIntegrationTest.JWT).isEmpty());assertThrows(ArenaOpsException.class,()->service.confirm(SessionCheckoutIntegrationTest.JWT,id,new Confirm(null)));assertThrows(ArenaOpsException.class,()->service.cancel(SessionCheckoutIntegrationTest.JWT,id));}
 @Test void expiredAbandonedRequestsAreHiddenScrubbedAndDeleted(){submit(issue());var id=checkins.findAll().get(0).getId();tx.executeWithoutResult(t->{var c=checkins.findById(id).orElseThrow();c.setExpiresAt(Instant.now().minusSeconds(1));checkins.save(c);});assertTrue(service.pending(SessionCheckoutIntegrationTest.JWT).isEmpty());assertThrows(ArenaOpsException.class,()->service.confirm(SessionCheckoutIntegrationTest.JWT,id,new Confirm(null)));service.cleanup();var c=checkins.findById(id).orElseThrow();assertEquals("EXPIRED",c.getStatus());assertNull(c.getCustomerName());assertNull(c.getMobile());tx.executeWithoutResult(t->{c.setExpiresAt(Instant.now().minus(Duration.ofDays(2)));checkins.save(c);});service.cleanup();assertTrue(checkins.findAll().isEmpty());}
 @Test void cancelAndConfirmedRetentionRemovePersonalDataButKeepSessionLink(){submit(issue());var c=checkins.findAll().get(0);service.cancel(SessionCheckoutIntegrationTest.JWT,c.getId());assertNull(checkins.findById(c.getId()).orElseThrow().getMobile());submit(issue());var active=checkins.findAll().stream().filter(v->"PENDING".equals(v.getStatus())).findFirst().orElseThrow();var r=service.confirm(SessionCheckoutIntegrationTest.JWT,active.getId(),new Confirm(null));tx.executeWithoutResult(t->{var v=checkins.findById(active.getId()).orElseThrow();v.setConfirmedAt(Instant.now().minus(Duration.ofDays(2)));checkins.save(v);});service.cleanup();var retained=checkins.findById(active.getId()).orElseThrow();assertNull(retained.getCustomerName());assertNull(retained.getMobile());assertEquals(r.sessionId(),retained.getSessionId());}
 @Test void simultaneousSubmissionsConsumeChallengeOnce()throws Exception{var q=issue();var pool=Executors.newFixedThreadPool(2);var go=new CountDownLatch(1);try{List<Future<Boolean>> tasks=new ArrayList<>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{go.await();try{submit(q);return true;}catch(ArenaOpsException e){return false;}}));go.countDown();int wins=0;for(var task:tasks)if(task.get(10,TimeUnit.SECONDS))wins++;assertEquals(1,wins);assertEquals(1,checkins.findAll().size());}finally{pool.shutdownNow();}}
 @Test void concurrentConfirmationsCreateOneActiveSession()throws Exception{submit(issue());var id=checkins.findAll().get(0).getId();var pool=Executors.newFixedThreadPool(2);var go=new CountDownLatch(1);try{List<Future<Boolean>> tasks=new ArrayList<>();for(int i=0;i<2;i++)tasks.add(pool.submit(()->{SessionCheckoutIntegrationTest.ACTOR.set(owner);go.await();try{service.confirm(SessionCheckoutIntegrationTest.JWT,id,new Confirm(null));return true;}catch(ArenaOpsException e){return false;}finally{SessionCheckoutIntegrationTest.ACTOR.remove();}}));go.countDown();int wins=0;for(var task:tasks)if(task.get(10,TimeUnit.SECONDS))wins++;assertEquals(1,wins);assertEquals(1,sessions.findAll().size());}finally{pool.shutdownNow();}}
 @Test void publicResponsesHaveNoCustomerOrPrivateIdentifiers(){assertEquals(Set.of("facility","expiresAt","formToken"),Arrays.stream(PublicInfo.class.getRecordComponents()).map(v->v.getName()).collect(java.util.stream.Collectors.toSet()));assertEquals(Set.of("status","expiresAt"),Arrays.stream(Receipt.class.getRecordComponents()).map(v->v.getName()).collect(java.util.stream.Collectors.toSet()));}
 @Test void requestLoggingRepresentationsDoNotExposeTokensOrPersonalData(){var q=issue();var body=new Submission(q.token(),"Private Name","+919876543210",true);assertFalse(body.toString().contains("Private Name"));assertFalse(body.toString().contains(q.token()));assertFalse(q.toString().contains(q.token()));assertFalse(new Token(q.token()).toString().contains(q.token()));}

}
